const puzzles = [];
function add(difficulty, id, category, instructions, lowLabel, highLabel, source, unit, rows, note = '') {
  const keys = Array.isArray(source) ? source : [source];
  puzzles.push({ id, title: id, category, difficulty, instructions, lowLabel, highLabel, note,
    sources: keys.map(key => ({ title: references[key][0], url: references[key][1] })),
    items: rows.map(([label, value, display]) => ({ label, value,
      valueLabel: display || `${value.toLocaleString('en-US', { maximumSignificantDigits: 6 })}${unit ? ` ${unit}` : ''}` })) });
}

